 {name:"长刀一式",windup:.11,active:.11,recovery:.17,damage:12,posture:14,range:100,level:1},
 {name:"长刀二式",windup:.13,active:.11,recovery:.18,damage:14,posture:17,range:104,level:1},
 {name:"长刀三式",windup:.21,active:.11,recovery:.3,damage:21,posture:27,range:111,level:2}
