 update(dt){dt=Math.min(.05,dt);this.time+=dt;this.logs.forEach(l=>l.ttl-=dt);this.logs=this.logs.filter(l=>l.ttl>0);this.particles.forEach(p=>{p.x+=p.vx*dt;p.y+=p.vy*dt;p.ttl-=dt});this.particles=this.particles.filter(p=>p.ttl>0);this.shake=Math.max(0,this.shake-dt*30);if(input.pressed("restart"))this.reset(true);if(!this.running||this.resultShown)return;if(this.hitStop>0){this.hitStop-=dt;return}this.updatePlayer(dt);this.updateEnemy(dt);this.tick(this.player,dt);this.tick(this.enemy,dt);for(const f of [this.player,this.enemy]){f.pos.x=clamp(f.pos.x,190,1090);f.pos.y=clamp(f.pos.y,180,615)}this.finish()}
 updatePlayer(dt){const p=this.player;if(!p.alive()||p.stagger>0)return;if(input.pressed("switch")&&p.state==="idle"){p.style=1-p.style;this.syncStyle();this.log(`换式：${styles[p.style].name}`)}if(input.pressed("dodge")&&["idle","guard"].includes(p.state))this.dodge();if(input.pressed("skill1"))this.skill(0);if(input.pressed("skill2"))this.skill(1);if(input.pressed("attack"))this.playerAttack();if(input.held.guard&&p.state==="idle"){p.state="guard";p.guardAt=this.time}if(!input.held.guard&&p.state==="guard")p.state="idle";if(["idle","guard"].includes(p.state)){const k={x:(input.keys.has("KeyD")||input.keys.has("ArrowRight")?1:0)-(input.keys.has("KeyA")||input.keys.has("ArrowLeft")?1:0),y:(input.keys.has("KeyS")||input.keys.has("ArrowDown")?1:0)-(input.keys.has("KeyW")||input.keys.has("ArrowUp")?1:0)},m=Math.hypot(input.move.x,input.move.y)>Math.hypot(k.x,k.y)?input.move:k,n=unit(m.x,m.y),speed=255*(p.state==="guard"?.48:1)*clamp(Math.hypot(m.x,m.y),0,1);p.pos.x+=n.x*speed*dt;p.pos.y+=n.y*speed*dt;if(distance(p.pos,this.enemy.pos)<430)p.faceToward(this.enemy.pos)}}
 updateEnemy(dt){const e=this.enemy;if(!e.alive()||e.stagger>0||e.state!=="idle")return;e.faceToward(this.player.pos);const d=distance(e.pos,this.player.pos);if(d>88){const n=unit(this.player.pos.x-e.pos.x,this.player.pos.y-e.pos.y);e.pos.x+=n.x*155*dt;e.pos.y+=n.y*155*dt}e.attackCooldown-=dt;if(d<116&&e.attackCooldown<=0)e.chooseAttack()}
 tick(f,dt){f.flash=Math.max(0,f.flash-dt);f.invuln=Math.max(0,f.invuln-dt);f.perfect=Math.max(0,f.perfect-dt);if(f.stagger>0){f.stagger-=dt;if(f.stagger<=0&&f.alive()){if(f.posture<=0)f.posture=f.maxPosture*.45;f.state="idle";f.attack=null;if(f.kind==="enemy")f.attackCooldown=.65}return}if(!f.attack){if(f.state==="idle")f.posture=Math.min(f.maxPosture,f.posture+8*dt);return}f.timer+=dt;const a=f.attack;if(f.timer>=a.windup&&f.timer<a.windup+a.active){f.state="active";if(!f.hit){f.hit=true;this.resolve(f,f===this.player?this.enemy:this.player,a)}}else if(f.timer>=a.windup+a.active+a.recovery){f.attack=null;f.hit=false;f.timer=0;f.state="idle";if(f.kind==="enemy")f.attackCooldown=.3}else if(f.timer>=a.windup+a.active)f.state="recover"}
 start(f,a){f.attack={...a};f.timer=0;f.hit=false;f.state="windup";f.faceToward(f===this.player?this.enemy.pos:this.player.pos);if(a.lunge){const n=f.forward();f.pos.x+=n.x*a.lunge;f.pos.y+=n.y*a.lunge}if(a.through){const n=unit(this.enemy.pos.x-f.pos.x,this.enemy.pos.y-f.pos.y);f.pos={x:this.enemy.pos.x+n.x*48,y:this.enemy.pos.y+n.y*48}}if(a.chase){const n=unit(this.enemy.pos.x-f.pos.x,this.enemy.pos.y-f.pos.y);f.pos={x:this.enemy.pos.x-n.x*54,y:this.enemy.pos.y-n.y*54}}if(f.kind==="enemy")this.telegraph=a}
 playerAttack(){const p=this.player;if(!["idle","guard","recover"].includes(p.state))return;if(this.enemy.posture<=0&&distance(p.pos,this.enemy.pos)<110){this.start(p,{name:"处决",windup:.18,active:.1,recovery:.42,damage:58,posture:0,range:120,level:3,execute:true});return}this.start(p,{...chain[p.combo]});p.combo=(p.combo+1)%chain.length}
 skill(slot){const p=this.player;if(!["idle","guard"].includes(p.state))return;if(p.edge<2){this.log("锋意不足：先用本流派的正确操作夺回节奏。");return}p.edge-=2;const moves=p.style===0?[{name:"震刃",windup:.16,active:.14,recovery:.28,damage:7,posture:38,range:132,level:2,radial:true},{name:"回锋",windup:.1,active:.12,recovery:.34,damage:25,posture:28,range:125,level:3,lunge:55}]:[{name:"掠影",windup:.08,active:.1,recovery:.2,damage:14,posture:14,range:120,level:1,through:true},{name:"追风斩",windup:.12,active:.11,recovery:.26,damage:23,posture:22,range:132,level:2,chase:true}];this.start(p,moves[slot]);this.log(`${moves[slot].name}：消耗二格锋意。`)}
 dodge(){const p=this.player,m=Math.hypot(input.move.x,input.move.y)>.05?input.move:p.forward(),n=unit(m.x,m.y);p.pos.x+=n.x*62;p.pos.y+=n.y*62;p.invuln=.28;p.perfect=.13;this.start(p,{name:"闪身",windup:.36,active:0,recovery:0,damage:0,posture:0,range:0,level:0,dodge:true})}
 resolve(a,d,m){if(m.dodge)return;if(distance(a.pos,d.pos)>m.range)return;if(d.invuln>0){if(d.perfect>0){if(d===this.player&&d.style===1)d.edge=Math.min(3,d.edge+1);this.initiative=clamp(this.initiative+(d===this.player?18:-18),-100,100);this.log(d.style===1?"流影 · 完美闪避：锋意 +1。":"完美闪避。");this.spark(d.pos,"#79c8b8",14)}return}if(a.attack&&d.attack&&d.state==="active"&&!m.unblockable&&!d.attack.unblockable){const al=m.level||1,dl=d.attack.level||1;if(al===dl){a.posture=Math.max(0,a.posture-9);d.posture=Math.max(0,d.posture-9);this.log("对刀：双刃相抵。") }else{const win=al>dl?a:d,lose=win===a?d:a;lose.posture=Math.max(0,lose.posture-24);lose.stagger=.38;lose.state="stagger";lose.attack=null;if(win===this.player&&win.style===0)win.edge=Math.min(3,win.edge+1);this.initiative=clamp(this.initiative+(win===this.player?25:-25),-100,100);this.log(win===this.player?"压刀：锋意 +1。":"崩刀：你的刀被压开。") }this.hitStop=.055;this.shake=7;this.spark(a.pos,"#e7dfcf",18);return}if(d===this.player&&d.state==="guard"&&!m.unblockable){if(this.time-d.guardAt<=.19){a.posture=Math.max(0,a.posture-36);a.stagger=.46;a.state="stagger";a.attack=null;if(d.style===0)d.edge=Math.min(3,d.edge+1);this.initiative=clamp(this.initiative+30,-100,100);this.log("听刃 · 精准弹反：锋意 +1。");this.spark(d.pos,"#91bfb3",22);this.checkPosture(a)}else{d.posture=Math.max(0,d.posture-m.posture*.72);this.log("格挡成功，但架势承压。");this.checkPosture(d)}return}d.health=Math.max(0,d.health-m.damage);if(!m.execute)d.posture=Math.max(0,d.posture-m.posture*.34);d.flash=.14;this.initiative=clamp(this.initiative+(a===this.player?10:-13),-100,100);this.log(m.execute?"处决。":`${m.name}命中。`);this.hitStop=m.execute?.11:.035;this.shake=m.unblockable?10:5;this.spark(d.pos,m.unblockable?"#ad3826":"#ddd4c1",m.execute?28:13);this.checkPosture(d)}
 checkPosture(f){if(f.posture<=0&&f.alive()){f.stagger=1.75;f.state="stagger";f.attack=null;this.log(`${f.kind==="player"?"无铭者":"执刃者"}架势崩溃！`)}}
