 spark(p,color,count){for(let i=0;i<count;i++){const a=Math.random()*Math.PI*2,s=70+Math.random()*220;this.particles.push({x:p.x,y:p.y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,ttl:.18+Math.random()*.2,color})}}
 finish(){if(!this.player.alive())this.show("试刃失败","灰窑再铸","回想刚才是早挡、贪刀，还是把红招当成了普通刀。");else if(!this.enemy.alive())this.show("执刃者倒下","错籍之一","铭牌背面刻着：我有名，不是这个。换一种军式，再赢一次。")}
